"""Small stdio LSP endpoint for the Taplo command."""
import json
import sys

CAPABILITIES = {
    "textDocumentSync": 1,
    "hoverProvider": True,
    "completionProvider": {"resolveProvider": False, "triggerCharacters": [".", "=", "[", "{", ",", '"']},
    "documentSymbolProvider": True,
    "documentFormattingProvider": True,
    "renameProvider": {"prepareProvider": True},
    "documentLinkProvider": {},
    "foldingRangeProvider": True,
    "workspace": {"workspaceFolders": {"supported": True, "changeNotifications": True}},
    "semanticTokensProvider": {
        "workDoneProgress": False,
        "legend": {"tokenTypes": ["tomlArrayKey", "tomlTableKey"], "tokenModifiers": ["readonly"]},
        "range": False,
        "full": True,
    },
}


def _help():
    return ("Run the language server over the standard input and output\n\n"
            "Usage: taplo lsp stdio [OPTIONS]\n\nOptions:\n"
            "      --colors <COLORS>\n          [default: auto]\n\n"
            "          Possible values:\n          - auto:   Determine whether to colorize output automatically\n"
            "          - always: Always colorize output\n          - never:  Never colorize output\n\n"
            "      --verbose\n          Enable a verbose logging format\n\n"
            "      --log-spans\n          Enable logging spans\n\n"
            "  -h, --help\n          Print help (see a summary with '-h')\n")


def run(args):
    if not args or args[0] in ("-h", "--help", "help"):
        sys.stdout.write("Language server operations\n\nUsage: taplo lsp [OPTIONS] <COMMAND>\n\nCommands:\n  tcp    Run the language server and listen on a TCP address\n  stdio  Run the language server over the standard input and output\n  help   Print this message or the help of the given subcommand(s)\n\nOptions:\n  -c, --config <CONFIG>\n          Path to the Taplo configuration file\n          \n          [env: TAPLO_CONFIG=]\n\n      --colors <COLORS>\n          [default: auto]\n\n          Possible values:\n          - auto:   Determine whether to colorize output automatically\n          - always: Always colorize output\n          - never:  Never colorize output\n\n      --cache-path <CACHE_PATH>\n          Set a cache path\n\n      --verbose\n          Enable a verbose logging format\n\n      --log-spans\n          Enable logging spans\n\n      --no-auto-config\n          Do not search for a configuration file\n\n  -h, --help\n          Print help (see a summary with '-h')\n")
        return 2 if not args else 0
    if args[0] == "stdio" and any(x in ("-h", "--help") for x in args[1:]):
        sys.stdout.write(_help())
        return 0
    if args[0] != "stdio":
        return 2
    stream = sys.stdin.buffer
    initialized = False
    pending_diagnostics = []

    def send(message):
        payload = json.dumps(message, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        sys.stdout.buffer.write(b"Content-Length: " + str(len(payload)).encode() + b"\r\n\r\n" + payload)
        sys.stdout.buffer.flush()

    while True:
        headers = {}
        while True:
            line = stream.readline()
            if not line:
                return 0
            if line in (b"\r\n", b"\n"):
                break
            if b":" in line:
                k, v = line.decode("ascii", "replace").split(":", 1)
                headers[k.strip().lower()] = v.strip()
        try:
            size = int(headers.get("content-length", "0"))
            request = json.loads(stream.read(size).decode("utf-8"))
        except Exception:
            return 1
        method = request.get("method")
        if method == "exit":
            return 0
        if method is None and request.get("id") == 0:
            # The editor's workspace/configuration reply unblocks diagnostics
            # for documents opened during initialization.
            for uri in pending_diagnostics:
                send({"jsonrpc": "2.0", "method": "textDocument/publishDiagnostics",
                      "params": {"uri": uri, "diagnostics": []}})
            pending_diagnostics.clear()
            continue
        if "id" not in request:
            if method == "initialized":
                initialized = True
            elif method == "textDocument/didOpen" and initialized:
                uri = request.get("params", {}).get("textDocument", {}).get("uri", "")
                pending_diagnostics.append(uri)
                send({"jsonrpc": "2.0", "id": 0, "method": "workspace/configuration",
                      "params": {"items": [{"section": "evenBetterToml"}]}})
